cd /tmp/src/time-i-gram; S=src/gosling-schema/gosling.schema.json; python3 -c "
import json;s=json.load(open('$S'));d=s['definitions']
for k in d:
  if 'Time' in k or 'Csv' in k or 'Period' in k or 'Transform' in k or 'Link' in k: print(k)
"; grep -n "separator\|isoWeek\|includesCalendarWeek\|weekFormat" $S | head -30

content.content:
CSVTimeData {
 "additionalProperties": false,
 "description": "Temporal data in a CSV (or other delimiter-separated) file. Time fields are converted to Unix epoch seconds, the coordinates of a temporal axis.",
 "properties": {
  "dateFields": {
   "description": "Fields with dates, converted to Unix seconds and stored in the first field:\n- one field: a date or date-time string (e.g., `2012-01-31`, `01/31/2012`, `31.01.2012`, `2012-01-31 16:40:21`), or an ISO week (`2012-W40` is its Monday, `2012-W40-3` its Wednesday; also `2012W40`, `2012W403`);\n- two fields: a date and a time of day (`16:40:21`, `0:05`, `7:21 PM`), or a year and a calendar week (with `includesCalendarWeek`);\n- three or more fields: date components named `year`, `month`, `day`, `hour`, `minute`, `second`.\n\nDate-times without a time zone are read as UTC. Unparseable dates are not drawn and log a warning.",
   "items": {
    "type": "string"
   },
   "type": "array"
  },
  "dayFirstDate": {
   "description": "Read ambiguous dates as day-month-year (e.g., `01.02.2012` is 1 February). The order is otherwise detected: a four-digit first part is year-month-day, a first part above 12 is day-first, anything else is month-day-year.",
   "type": "boolean"
  },
  "includesCalendarWeek": {
   "description": "With two `dateFields`, read the second one as a calendar week of the year in the first one.",
   "type": "boolean"
  },
  "interval": {
   "description": "Start and end fields of an interval (e.g., `[\"pickup\", \"dropoff\"]`), each converted to Unix seconds: numbers as Unix timestamps (see `timestampUnit`), anything else as a date. Encode them with `x` and `xe`.",
   "items": {
    "type": "string"
   },
   "type": "array"
  },
  "sampleLength": {
   "description": "Opt-in random sampling: the maximum number of rows per tile. When a tile has more rows, a random sample of this size is drawn, so some rows are not shown.\n\n__Default:__ no sampling (all rows are shown)",
   "type": "number"
  },
  "separator": {
   "description": "Field separator. __Default:__ `\",\"`",
   "type": "string"
  },
  "timestampField": {
   "description": "Field with Unix timestamps (see `timestampUnit`).",
   "type": "string"
  },
  "timestampUnit": {
   "$ref": "#/definitions/TimestampUnit",
   "description": "Unit of the Unix timestamps in `timestampField` and in numeric `interval` columns: seconds (`\"s\"`) or milliseconds (`\"ms\"`).\n\n__Default:__ `\"s\"`"
  },
  "type": {
   "const": "csv-time",
   "description": "Define data type.",
   "type": "string"
  },
  "url": {
   "description": "URL of the CSV file.",
   "type": "string"
  },
  "yearFirstDate": {
   "description": "Read dates as year-month-day.",
   "type": "boolean"
  }
 },
 "required": [
  "type",
  "url"
 ],
 "type": "object"
}
-----
DataTransform {
 "anyOf": [
  {
   "$ref": "#/definitions/FilterTransform"
  },
  {
   "$ref": "#/definitions/IntervalTransform"
  },
  {
   "$ref": "#/definitions/TimeUnitTransform"
  },
  {
   "$ref": "#/definitions/SpanTransform"
  },
  {
   "$ref": "#/definitions/StrConcatTransform"
  },
  {
   "$ref": "#/definitions/StrReplaceTransform"
  },
  {
   "$ref": "#/definitions/LogTransform"
  },
  {
   "$ref": "#/definitions/DisplaceTransform"
  },
  {
   "$ref": "#/definitions/ExonSplitTransform"
  },
  {
   "$ref": "#/definitions/GenomicLengthTransform"
  },
  {
   "$ref": "#/definitions/SvTypeTransform"
  },
  {
   "$ref": "#/definitions/CoverageTransform"
  },
  {
   "$ref": "#/definitions/JsonParseTransform"
  }
 ]
}
-----
FilterTransform {
 "anyOf": [
  {
   "$ref": "#/definitions/OneOfFilter"
  },
  {
   "$ref": "#/definitions/RangeFilter"
  },
  {
   "$ref": "#/definitions/IncludeFilter"
  }
 ]
}
-----
TimeUnitTransform {
 "additionalProperties": false,
 "description": "Truncate a time field (Unix seconds) to the start of the calendar unit that contains it (UTC), e.g. the first instant of its month. Rows are kept; to aggregate by unit, use `x.timeUnit` with an `aggregate` channel.",
 "properties": {
  "endField": {
   "description": "If specified, a field that receives the end of the unit (the start of the next one), e.g. for `xe`.",
   "type": "string"
  },
  "field": {
   "description": "Field with times in Unix seconds, e.g. a `dateFields` field of `csv-time` or `json-time` data.",
   "type": "string"
  },
  "labelField": {
   "description": "If specified, a field that receives a readable name of the unit, e.g. for `color`, `row` or `text`: `\"1960s\"` (decade), `\"1960\"` (year), `\"1960-Q1\"` (quarter), `\"1960-03\"` (month), `\"1960-W09\"` (ISO week), `\"1960-03-01\"` (day), `\"1960-03-01 14:00\"` (hour, minute), `\"1960-03-01 14:00:05\"` (second, millisecond).",
   "type": "string"
  },
  "newField": {
   "description": "Field that receives the start of the unit. __Default:__ `field` itself",
   "type": "string"
  },
  "type": {
   "const": "timeUnit",
   "type": "string"
  },
  "unit": {
   "$ref": "#/definitions/TimeUnit",
   "description": "The calendar unit. `week` is the ISO week (Monday to Sunday)."
  }
 },
 "required": [
  "type",
  "field",
  "unit"
 ],
 "type": "object"
}
-----
Period {
 "additionalProperties": false,
 "properties": {
  "newField": {
   "description": "Field that receives each row's period, as a string that sorts chronologically: `\"1960s\"` (decade), `\"1961\u20131970\"` (decade with `start`), `\"2010\"` (year), `\"2010/11\"` (year with `start`), `\"2010-03\"` (month), `\"2010-W05\"` (week), `\"2010-03-01\"` (day).\n\n__Default:__ `\"<field>_<unit>\"`, e.g. `\"date_year\"`",
   "type": "string"
  },
  "start": {
   "description": "Where each period begins: the last digit of the first year (0-9) for decades (e.g. `1` for 1961-1970), a month (1-12) for calendar years (e.g. `8` for August-July seasons), an ISO week (1-52) for week-based years (e.g. `40` for flu seasons), a weekday (1 = Monday ... 7 = Sunday) for weeks, an hour (0-23) for days. Not supported for months.\n\n__Default:__ a year ending in 0, the first month, week, weekday (Monday) or hour (0)",
   "type": "number"
  },
  "unit": {
   "$ref": "#/definitions/PeriodUnit",
   "description": "The calendar period."
  },
  "weekBased": {
   "description": "Use years made of ISO weeks (only for `unit: \"year\"`): a time is placed by its ISO week and weekday, so ISO week 1 is always at the start of the period, even when it begins in late December, and the period of a row is its ISO week-year. Years without a week 53 leave the last week empty.\n\n__Default:__ `false`",
   "type": "boolean"
  }
 },
 "required": [
  "unit"
 ],
 "type": "object"
}
-----
PeriodUnit {
 "description": "Calendar periods by which a temporal axis can be wrapped.",
 "enum": [
  "decade",
  "year",
  "month",
  "week",
  "day"
 ],
 "type": "string"
}
-----
TimeUnit {
 "description": "The calendar granularity hierarchy, all in UTC. `week` is the ISO week (Monday to Sunday); quarters start in January, April, July and October; decades start in years divisible by 10.",
 "enum": [
  "millisecond",
  "second",
  "minute",
  "hour",
  "day",
  "week",
  "month",
  "quarter",
  "year",
  "decade"
 ],
 "type": "string"
}
-----
TimeInterval {
 "additionalProperties": false,
 "properties": {
  "interval": {
   "description": "Show a certain time interval, as `[start, end]`. Each bound is Unix epoch seconds or a date string: a partial date (`\"2010\"`, `\"2010-12\"`, `\"2010-12-31\"`, `\"2010-Q4\"`, `\"2015-W53\"`) starts at the first instant of the unit it names and, as the end, includes the whole unit (`[\"2000-01\", \"2010-12\"]` covers January 2000 through December 2010); a date-time (`\"2010-01-03T23:00:00Z\"`) is that exact instant, read as UTC without a zone.",
   "items": {
    "$ref": "#/definitions/TimeValue"
   },
   "maxItems": 2,
   "minItems": 2,
   "type": "array"
  }
 },
 "required": [
  "interval"
 ],
 "type": "object"
}
-----
TimeValue {
 "description": "A time: Unix epoch seconds, or a date string such as `\"2010-12\"` or `\"2010-01-03T23:00:00Z\"` (UTC).",
 "type": [
  "number",
  "string"
 ]
}
-----
Shell cwd was reset to /work

