import type {
    SpanTransform,
    PeriodUnit,
    TimeUnit,
    TimeUnitRule,
    X,
    ChannelDeep,
    CommonTrackDef,
    CommonViewDef,
    GoslingSpec,
    SingleTrack,
    Track,
    VisibilityCondition
} from '@gosling-lang/gosling-schema';
import { IsChannelDeep, IsOverlaidTrack, getTemporalChannelFromTrack } from '@gosling-lang/gosling-schema';
import { TIME_UNITS, UNIT_SECONDS, parseDuration, parseTimeValue } from '../core/utils/time-units';
import {
    ABSOLUTE_TIME,
    PERIOD_UNITS,
    describeTimeCoordinates,
    describeAnchor,
    getTrackTimeCoordinates,
    RELATIVE_UNITS,
    type RelativeAnchor,
    type RelativeConfig,
    type RelativeTime,
    periodCoordinates,
    periodKeyField,
    periodReference,
    periodStartRange,
    setTrackTimeCoordinates,
    timeCoordinateSignature,
    type TimeCoordinateSystem,
    type TrackTimeCoordinates,
    TIME_AGGREGATE_OPS,
    getTrackTimeUnit,
    setTrackTimeUnit,
    setTrackTimeUnitTiling,
    unitsWithinPeriod,
    type TimeAggregateOp,
    type TimeUnitBinning
} from '../core/utils/time-coordinate-system';
import { traverseTracksAndViews } from './spec-preprocess';
import { resetTemporalWarnings } from '../core/utils/temporal-warnings';

const X_CHANNELS = ['x', 'xe', 'x1', 'x1e'] as const;

/**
 * Resolve the temporal syntactic sugar of a spec, after `traverseToFixSpecDownstream()`:
 * date strings in time intervals and durations in `visibility` thresholds and `zoomLimits` become seconds.
 * Downstream code (compiler, tracks, fetchers) therefore only sees numbers. Invalid uses are removed with a
 * warning; the returned messages are the same warnings.
 *
 * Idempotent: resolved tracks are flagged and skipped (see `RESOLVED`), and numbers in view domains are kept as
 * they are, so the function can run again after a responsive re-fix.
 */
export function resolveTemporalSugar(spec: GoslingSpec): string[] {
    // a new spec: render-time warnings may be given again
    resetTemporalWarnings();
    const messages: string[] = [];
    const warn = (message: string) => {
        messages.push(message);
        console.warn(`[time-i-gram] ${message}`);
    };

    // Tracks first: a view's `xDomain` object is shared by reference with the `x.domain` of its tracks, and
    // only a track knows whether its channel is temporal (strings) or genomic (no strings allowed).
    const views: (CommonViewDef | CommonTrackDef)[] = [spec];
    traverseTracksAndViews(spec, tv => {
        if (IsTrackDef(tv)) resolveTrack(tv as Track, warn);
        else views.push(tv);
    });
    views.forEach(view => resolveViewDef(view, warn));
    return messages;
}

type Warn = (message: string) => void;

/**
 * After `traverseToFixSpecDownstream()`, views hold `tracks` or `views`; tracks hold neither
 * (flattened overlaid tracks keep a `tracks: undefined` key).
 */
function IsTrackDef(tv: CommonViewDef | CommonTrackDef) {
    return !(tv as { tracks?: unknown }).tracks && !(tv as { views?: unknown }).views;
}

/** View-level `xDomain` and `zoomLimits`; strings in a view's `xDomain` are always time values. */
function resolveViewDef(def: CommonViewDef | CommonTrackDef, warn: Warn) {
    const { xDomain } = def;
    if (xDomain && 'interval' in xDomain && !('chromosome' in xDomain)) {
        const resolved = resolveInterval(xDomain.interval, warn);
        if (resolved) xDomain.interval = resolved;
        else def.xDomain = undefined;
    }
}

/** Properties of temporal x channels that have no meaning on other channels. */
const TEMPORAL_ONLY_PROPERTIES = ['period', 'timeUnit', 'relative'] as const;

/** Remove temporal-only properties from non-temporal x channels (also a schema error), with a warning. */
function removeTemporalOnlyProperties(track: Track, warn: Warn) {
    const members: Partial<SingleTrack>[] = IsOverlaidTrack(track) ? [track, ...track.overlay] : [track as SingleTrack];
    members.forEach(member =>
        X_CHANNELS.forEach(key => {
            const channel = member[key] as Record<string, unknown> | undefined;
            if (!IsChannelDeep(channel as ChannelDeep) || channel!.type === 'temporal') return;
            TEMPORAL_ONLY_PROPERTIES.forEach(prop => {
                if (channel![prop] === undefined) return;
                warn(`${key}.${prop} only applies to temporal channels (type: "temporal"), so it is ignored.`);
                delete channel![prop];
            });
        })
    );
}

/** What a bound of a time interval is: a date string, a duration string, a number (seconds) or neither. */
function boundKind(value: number | string): 'date' | 'duration' | 'number' | 'invalid' {
    if (typeof value === 'number') return 'number';
    if (!isNaN(parseTimeValue(value))) return 'date';
    return isNaN(parseDuration(value)) ? 'invalid' : 'duration';
}

/**
 * Drop temporal x domains of the wrong kind, before their strings are converted: durations on an absolute axis,
 * and dates on a relative axis (whose domain is offsets). A relative axis also ignores a view-level `xDomain`
 * unless it is given as durations, since a view's domain is usually in absolute time.
 */
function checkDomainKinds(track: Track, warn: Warn) {
    const inherited = (track as CommonTrackDef).xDomain;
    const members: Partial<SingleTrack>[] = IsOverlaidTrack(track) ? [track, ...track.overlay] : [track as SingleTrack];
    members.forEach(member => {
        const x = member.x;
        if (!IsChannelDeep(x) || x.type !== 'temporal' || !x.domain || !('interval' in (x.domain as object))) return;
        const interval = (x.domain as { interval: (number | string)[] }).interval;
        const kinds = interval.map(boundKind);
        const isInherited = JSON.stringify(x.domain) === JSON.stringify(inherited);
        if ('relative' in x && x.relative) {
            if (kinds.includes('date') || (isInherited && !kinds.every(k => k === 'duration'))) {
                warn(
                    `x.domain ${JSON.stringify(
                        interval
                    )}: a relative axis takes offsets (e.g. ["-6 months", "6 months"]), ` +
                        'not dates, so the domain is ignored; set the offsets on x.domain.'
                );
                x.domain = undefined;
            }
        } else if (!('period' in x && x.period) && kinds.includes('duration')) {
            warn(
                `x.domain ${JSON.stringify(
                    interval
                )}: an absolute time axis takes dates, not durations, so the domain is ignored.`
            );
            x.domain = undefined;
        }
    });
}

/**
 * Set on every temporal track that `resolveTemporalSugar()` has resolved. The compiler runs the pass again after
 * a responsive re-fix, which swaps in unresolved views: tracks with the flag are skipped, the others resolved.
 * Other tracks are not flagged (so their compiled specs stay as they were): resolving them again changes nothing.
 */
