                const timeCoordinates = this.dataConfig.timeCoordinates;
                if (timeCoordinates) this.values = applyTimeCoordinates(this.values.filter(Boolean), timeCoordinates);
            })
                .catch(error => {
                    console.error(error);
                });
        }

        async fetchData(): Promise<any> {
            const { url } = this.dataConfig;
            return fetch(url)
                .then(response => {
                    if (!response.ok) {
                        throw new Error(`HTTP error! status: ${response.status}`);
                    }
                    return response.text();
                })
                .catch(error => {
                    console.error(`Error fetching data: ${error}`);
                    return Promise.reject(error);
                });
        }

        isValidTimestamp(value: number) {
            if (isNaN(value)) {
                return false;
            }
            const date = new Date(value);
            return !isNaN(date.getTime());
        }

